def transform(grid):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]; out=[r[:] for r in grid]
    # Rays are drawn in the direction indicated by the colored marker shapes.
    # 5 is a downward vertical ray; 8 is down-left. Two-cell diagonal
    # markers extend their diagonals in both directions.
    for color in (5,8,9,2):
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if not pts: continue
        if color==5:
            # single marker extends downward
            r,c=min(pts)
            while r+1<h:
                r+=1
                if out[r][c]==bg: out[r][c]=color
        elif color==8:
            # diagonal down-left from the lower-leftmost 8
            r,c=max(pts)
            while r+1<h and c-1>=0:
                r+=1;c-=1
                if out[r][c]==bg: out[r][c]=color
        else:
            # infer diagonal from marker arrangement; 9 down-left, 2 down-right
            dr,dc=(1,-1) if color==9 else (1,1)
            # Extend each end of the line, retaining all existing cells.
            # Pair's top endpoint and bottom endpoint determine line.
            endpoints=pts
            for r,c in endpoints:
                for sr,sc in ((dr,dc),(-dr,-dc)):
                    rr,cc=r+sr,c+sc
                    while 0<=rr<h and 0<=cc<w:
                        if out[rr][cc]==bg: out[rr][cc]=color
                        rr+=sr;cc+=sc
    return out

